<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, ref } from 'vue';
import PageHeader from '@/components/common/PageHeader.vue';
import { practiceMonitorApi } from '@/api/coreFeatures';
import * as usersApi from '@/api/users';
import * as departmentsApi from '@/api/departments';
import * as banksApi from '@/api/banks';
import { TOKEN_KEY } from '@/api/http';
import type { Department, PracticeMonitorSummary, PracticeSessionMonitor, PracticeSessionStatus, QuestionBank, User } from '@/types';

const summary=ref<PracticeMonitorSummary>({activeUsers:0,sessionTotal:0,dailyActiveUsers:0,answerTotal:0,averageCorrectRate:0,wrongConsolidationRate:0,generatedAt:''});
const sessions=ref<PracticeSessionMonitor[]>([]);const logs=ref<Array<Record<string,unknown>>>([]);const status=ref<PracticeSessionStatus|''>('');const transport=ref<'sse'|'polling'>('polling');let poll:ReturnType<typeof setInterval>|null=null;let controller:AbortController|null=null;
const users=ref<User[]>([]);const departments=ref<Department[]>([]);const banks=ref<QuestionBank[]>([]);const userId=ref('');const departmentId=ref('');const bankId=ref('');const range=ref<[Date,Date]|null>(null);const tab=ref('sessions');
const filtered=computed(()=>sessions.value);
function dbTime(value:Date){return value.toISOString().slice(0,19).replace('T',' ')}
function params(){return {userId:userId.value||undefined,departmentId:departmentId.value||undefined,bankId:bankId.value||undefined,status:status.value||undefined,startAt:range.value?dbTime(range.value[0]):undefined,endAt:range.value?dbTime(range.value[1]):undefined}}
async function loadSessions(){sessions.value=await practiceMonitorApi.sessions(params())}
async function loadLogs(){logs.value=await practiceMonitorApi.logs(params())}
async function load(){const [nextSummary]=await Promise.all([practiceMonitorApi.overview(),loadSessions(),loadLogs()]);summary.value=nextSummary;}
function startPolling(){transport.value='polling';if(poll)return;poll=setInterval(()=>void load(),15000)}
async function connect(){controller=new AbortController();try{const token=localStorage.getItem(TOKEN_KEY);const res=await fetch('/api/practice-monitor/stream',{headers:token?{Authorization:`Bearer ${token}`}:{},signal:controller.signal});if(!res.ok||!res.body)throw new Error('SSE unavailable');transport.value='sse';const reader=res.body.getReader();const decoder=new TextDecoder();let buf='';for(;;){const {value,done}=await reader.read();if(done)break;buf+=decoder.decode(value,{stream:true});const parts=buf.split(/\r?\n\r?\n/);buf=parts.pop()??'';for(const part of parts){if(!part.includes('event: overview'))continue;const line=part.split(/\r?\n/).find(x=>x.startsWith('data:'));if(line)summary.value=JSON.parse(line.slice(5).trim()) as PracticeMonitorSummary;}void loadSessions();}if(!controller.signal.aborted)startPolling();}catch{if(!controller?.signal.aborted)startPolling()}}
onMounted(()=>{void load();void Promise.all([usersApi.list(),departmentsApi.list(),banksApi.list()]).then(([u,d,b])=>{users.value=u;departments.value=d;banks.value=b});void connect()});onBeforeUnmount(()=>{controller?.abort();if(poll)clearInterval(poll)});
</script>
<template><div class="page"><PageHeader title="练题监控" description="在线状态由 30 秒心跳判定，超过 90 秒无心跳显示离线；实时连接失败自动回退 15 秒轮询"><template #actions><el-tag :type="transport==='sse'?'success':'warning'">{{ transport==='sse'?'实时推送':'轮询模式' }}</el-tag><el-button @click="load">刷新</el-button></template></PageHeader><el-row :gutter="12"><el-col v-for="item in [{l:'当前在线',v:summary.activeUsers},{l:'今日活跃',v:summary.dailyActiveUsers},{l:'累计会话',v:summary.sessionTotal},{l:'累计作答',v:summary.answerTotal},{l:'平均正确率',v:`${summary.averageCorrectRate}%`},{l:'错题巩固率',v:`${summary.wrongConsolidationRate}%`}]" :key="item.l" :span="4"><el-card shadow="never"><div class="metric">{{ item.v }}</div><div class="label">{{ item.l }}</div></el-card></el-col></el-row><el-card shadow="never"><div class="filters"><el-select v-model="userId" clearable filterable placeholder="全部人员"><el-option v-for="u in users" :key="u.id" :label="u.name" :value="u.id"/></el-select><el-select v-model="departmentId" clearable filterable placeholder="全部科室"><el-option v-for="d in departments" :key="d.id" :label="d.name" :value="d.id"/></el-select><el-select v-model="bankId" clearable filterable placeholder="全部题库"><el-option v-for="b in banks" :key="b.id" :label="b.name" :value="b.id"/></el-select><el-select v-model="status" clearable placeholder="全部状态"><el-option label="在线" value="active"/><el-option label="离线" value="offline"/><el-option label="已完成" value="completed"/><el-option label="已退出" value="exited"/></el-select><el-date-picker v-model="range" type="datetimerange" start-placeholder="开始时间" end-placeholder="结束时间"/><el-button type="primary" @click="load">筛选</el-button></div><el-tabs v-model="tab"><el-tab-pane label="会话记录" name="sessions"><el-table :data="filtered"><el-table-column prop="userName" label="用户" width="120"/><el-table-column prop="departmentName" label="科室" width="140"/><el-table-column prop="bankName" label="题库" min-width="150"/><el-table-column prop="mode" label="方式" width="110"/><el-table-column label="进度" width="120"><template #default="{row}">{{ row.answeredCount }}/{{ row.questionCount }}</template></el-table-column><el-table-column label="正确率" width="100"><template #default="{row}">{{ row.answeredCount?Math.round(row.correctCount/row.answeredCount*100):0 }}%</template></el-table-column><el-table-column prop="status" label="状态" width="100"/><el-table-column prop="startedAt" label="开始时间" width="190"/><el-table-column prop="lastSeenAt" label="最后心跳" width="190"/></el-table></el-tab-pane><el-tab-pane label="逐题作答日志" name="logs"><el-table :data="logs"><el-table-column prop="userName" label="用户" width="120"/><el-table-column prop="bankName" label="题库" width="150"/><el-table-column prop="stem" label="题干" min-width="280" show-overflow-tooltip/><el-table-column label="结果" width="90"><template #default="{row}"><el-tag :type="row.correct?'success':'danger'">{{ row.correct?'正确':'错误' }}</el-tag></template></el-table-column><el-table-column prop="answer" label="作答" min-width="120"/><el-table-column prop="answeredAt" label="作答时间" width="190"/></el-table></el-tab-pane></el-tabs></el-card></div></template>
<style scoped>.page{display:flex;flex-direction:column;gap:16px}.metric{font-size:26px;font-weight:700}.label{color:var(--el-text-color-secondary);margin-top:6px}.filters{display:flex;gap:10px;margin-bottom:12px;flex-wrap:wrap}.filters>.el-select{width:150px}</style>
